/// Octave band centres of the decay tables, Hz.
pub const OCT: [f64; 9] = [
    63.0, 125.0, 250.0, 500.0, 1000.0, 2000.0, 4000.0, 8000.0, 16000.0,
];

/// One velocity layer.
pub struct Layer {
    /// Band curve, dB relative to the hit's total.
    pub curve: [f64; 28],
    /// Amplitude decay time constant per octave band, seconds.
    pub tau: [f64; 9],
    /// RMS of the first 0.3 s, dB relative to the hard layer.
    pub level_db: f64,
    /// Onset to peak, seconds.
    pub attack: f64,
}

/// A strong mode of the medium layer.
pub struct StrongMode {
    pub f: f64,
    /// Energy relative to the hit's total, dB.
    pub db: f64,
    /// Amplitude decay time constant, seconds.
    pub tau: f64,
}

/// A voice: soft, medium and hard layers and the strong modes.
pub struct VoiceData {
    pub layers: [Layer; 3],
    pub modes: &'static [StrongMode],
}

